import socket,sys,json
try:
 s=socket.create_connection((sys.argv[1],int(sys.argv[2])),2);s.sendall(b'probe');print(json.dumps({'probe':'tcp','allowed':s.recv(16)==b'canary'}))
except OSError as e:
 print(json.dumps({'probe':'tcp','allowed':False,'error':str(e)}))

